import{_ as n,o as s,c as t,ag as a}from"./chunks/framework.ySAk_w31.js";const g=JSON.parse(`{"title":"Étendre l'agent","description":"","frontmatter":{},"headers":[],"relativePath":"handout-04-etendre-l-agent.md","filePath":"handout-04-etendre-l-agent.md","handout":{"fichier":"handout-04-etendre-l-agent.md","markdown":"# Handout — Étendre l'agent\\n\\n**Développeur IA — Foundation · Zenika · fiche module 4**\\n\\nBrancher l'agent sur le reste du SI, et capitaliser ce qui marche, sans alourdir chaque appel.\\n\\n## Apporter le contexte de l'entreprise\\n\\n_Module 4 · slide « Apporter le contexte de l'entreprise »_\\n\\nDeux façons de donner à l'agent ce que **le dépôt ne contient pas** :\\n\\n|               | **RAG : vos documents**                                                | **Tools / MCP : vos applications**                                         |\\n| ------------- | ---------------------------------------------------------------------- | -------------------------------------------------------------------------- |\\n| **Apporte**   | de la connaissance : ADR, docs d'architecture, wiki, conventions d'API | des données vivantes et la capacité d'agir : tickets, base, CI, navigateur |\\n| **Exemple**   | « Quelle est notre convention de pagination ? »                        | « Lis le ticket BOOK-142, puis lance les tests e2e dans le navigateur. »   |\\n| **Vigilance** | des documents à jour, sinon des réponses périmées… mais sourcées       | des droits limités : l'agent agit avec vos accès                           |\\n\\n- **RAG** : les documents sont indexés à l'avance ; un tool trouve les passages pertinents ; seuls ces passages entrent dans la context window ; le modèle s'appuie dessus et cite ses sources. Pour le code, la recherche dans le dépôt joue déjà ce rôle ; le RAG sert pour ce qui n'est pas dans le dépôt.\\n- **MCP** (Model Context Protocol) : la prise standard des tools, l'« USB-C » des agents. Un serveur écrit une fois marche dans tous les harness compatibles, en local ou à distance. MCP n'apporte aucune « intelligence » : c'est de la plomberie standardisée.\\n- Le modèle choisit un tool sur sa **description** : nom, description et paramètres de chaque tool sont envoyés à chaque appel. Une mauvaise description = un tool mal utilisé ou ignoré.\\n\\n> Dans les deux cas, l'agent ne **sait** rien de plus : on lui **donne** le bon contexte, au bon moment.\\n\\n## MCP : ce que vous exposez en branchant un serveur\\n\\n_Module 4 · slide « MCP : ce que vous exposez en branchant un serveur »_\\n\\nBrancher un serveur, c'est laisser le modèle **décider seul** quelles données partent chez un tiers. Trois questions avant chaque branchement :\\n\\n| Question                                         | Ce qu'on vérifie                                                              |\\n| ------------------------------------------------ | ----------------------------------------------------------------------------- |\\n| **Qui l'exécute ?** Local ou distant             | Le local reste sur la machine. Le distant reçoit ce que le modèle lui envoie. |\\n| **Qui l'authentifie ?** Quel jeton, quels droits | Lecture, écriture, suppression : jamais plus large que la tâche.              |\\n| **Qui le maintient ?** Officiel ou fork          | Un serveur non maintenu est un risque ouvert.                                 |\\n\\n**Et ce qu'il coûte** : chaque serveur ajoute ses tool definitions à **chaque** appel, avant même le premier message. N'activez que ceux que vous utilisez **vraiment** pour ce projet. Une commande en ligne déjà installée, documentée dans une skill, coûte souvent moins de contexte qu'un serveur MCP complet.\\n\\n## Une bonne consigne devient une skill\\n\\n_Module 4 · slide « Une bonne consigne devient une skill »_\\n\\nUn **savoir-faire emballé** :\\n\\n- un **dossier** : un \`SKILL.md\`, plus des scripts, références et gabarits ;\\n- chargée **à la demande**, quand la tâche correspond : la **progressive disclosure** (l'agent ne voit d'abord que le nom et la description) ;\\n- la **description** dit quoi et quand : c'est elle qui déclenche ;\\n- testée en **session vierge** : une autre session la suit sans coaching.\\n\\nExemple, la skill « tests-api » :\\n\\n\`\`\`text\\ntests-api/SKILL.md\\n\\nname: tests-api\\ndescription: Écrire ou compléter les tests\\n  d'un endpoint. À utiliser dès qu'on\\n  ajoute ou modifie une route.\\n\\n- Un test par cas limite : liste vide,\\n  dernière page, curseur invalide.\\n- Données via tests/factories.\\n- Base de test réelle, pas de mock.\\n\`\`\`\\n\\n- On n'y met que ce que l'agent **ne peut pas déduire** ; quelques centaines de lignes au plus ; pas de chemins propres à un OS, de versions figées ni d'informations périmées.\\n- Un **script** embarqué donne le même résultat à chaque fois, là où la même logique en prose est réinterprétée ; et il n'entre pas dans la context window tant que l'agent ne l'ouvre pas.\\n- Si la skill ne se déclenche pas en session vierge, c'est presque toujours la **description** qu'il faut réécrire.\\n\\n> Une skill ne pèse dans la context window **que quand elle sert**.\\n\\n## Où ranger le contexte durable ?\\n\\n_Module 4 · slide « Quiz : où ranger le contexte durable ? »_\\n\\nLa règle qui tranche : **à quelle fréquence** le contenu doit-il être chargé ?\\n\\n| Où                      | Chargé                                  | Exemple                                                                                                                    |\\n| ----------------------- | --------------------------------------- | -------------------------------------------------------------------------------------------------------------------------- |\\n| **Instructions projet** | à chaque session                        | « Les tests se lancent avec npm test, jamais sur la base de prod » ; « TypeScript strict, handlers dans src/api/handlers » |\\n| **Demande initiale**    | pour une tâche                          | « Pour ce ticket : garder le schéma Page de /rooms »                                                                       |\\n| **Skill**               | à la demande, quand la tâche correspond | « Comment écrire un test d'API selon nos conventions » ; « La procédure de migration de schéma, avec son script »          |\\n| **Note de reprise**     | pour reprendre une session interrompue  | « Étapes 1 à 3 faites, l'étape 4 bloque sur le curseur »                                                                   |\\n\\n- Piège : « jamais sur la base de prod » pourrait sembler une skill ; elle doit valoir à chaque session, donc instructions projet.\\n- Tous ces fichiers sont **versionnés et relus comme du code** : ils entrent dans la context window de toute l'équipe.\\n\\n> Plus c'est **chargé souvent**, plus c'est **court** : à chaque session, pour une tâche, à la demande.\\n\\n## À retenir\\n\\n1. Tools et MCP branchent l'agent sur le SI, mais chaque branchement **expose** quelque chose et **pèse** dans chaque appel.\\n2. Une skill est un savoir-faire **chargé à la demande** ; sa description la déclenche.\\n3. Une consigne que tu répètes **trois fois** mérite une skill, testée en session vierge.\\n\\n**Mots-clés** : RAG, grounding, tools, MCP, tool definitions, skill, progressive disclosure, instructions projet, demande initiale — voir le glossaire.\\n"}}`),o={name:"handout-04-etendre-l-agent.md"};function r(i,e,l,u,d,c){return s(),t("div",null,[...e[0]||(e[0]=[a(`<p class="zh-type">fiche module 4</p><h1 id="handout-etendre-l-agent" tabindex="-1">Étendre l’agent <a class="header-anchor" href="#handout-etendre-l-agent" aria-label="Permalink to &quot;Handout — Étendre l&#39;agent&quot;">​</a></h1><p>Brancher l’agent sur le reste du SI, et capitaliser ce qui marche, sans alourdir chaque appel.</p><h2 id="apporter-le-contexte-de-l-entreprise" tabindex="-1">Apporter le contexte de l’entreprise <a class="header-anchor" href="#apporter-le-contexte-de-l-entreprise" aria-label="Permalink to &quot;Apporter le contexte de l&#39;entreprise&quot;">​</a></h2><p><em>Module 4 · slide « Apporter le contexte de l’entreprise »</em></p><p>Deux façons de donner à l’agent ce que <strong>le dépôt ne contient pas</strong> :</p><table tabindex="0"><thead><tr><th></th><th><strong>RAG : vos documents</strong></th><th><strong>Tools / MCP : vos applications</strong></th></tr></thead><tbody><tr><td><strong>Apporte</strong></td><td>de la connaissance : ADR, docs d’architecture, wiki, conventions d’API</td><td>des données vivantes et la capacité d’agir : tickets, base, CI, navigateur</td></tr><tr><td><strong>Exemple</strong></td><td>« Quelle est notre convention de pagination ? »</td><td>« Lis le ticket BOOK-142, puis lance les tests e2e dans le navigateur. »</td></tr><tr><td><strong>Vigilance</strong></td><td>des documents à jour, sinon des réponses périmées… mais sourcées</td><td>des droits limités : l’agent agit avec vos accès</td></tr></tbody></table><ul><li><strong>RAG</strong> : les documents sont indexés à l’avance ; un tool trouve les passages pertinents ; seuls ces passages entrent dans la context window ; le modèle s’appuie dessus et cite ses sources. Pour le code, la recherche dans le dépôt joue déjà ce rôle ; le RAG sert pour ce qui n’est pas dans le dépôt.</li><li><strong>MCP</strong> (Model Context Protocol) : la prise standard des tools, l’« USB-C » des agents. Un serveur écrit une fois marche dans tous les harness compatibles, en local ou à distance. MCP n’apporte aucune « intelligence » : c’est de la plomberie standardisée.</li><li>Le modèle choisit un tool sur sa <strong>description</strong> : nom, description et paramètres de chaque tool sont envoyés à chaque appel. Une mauvaise description = un tool mal utilisé ou ignoré.</li></ul><blockquote><p>Dans les deux cas, l’agent ne <strong>sait</strong> rien de plus : on lui <strong>donne</strong> le bon contexte, au bon moment.</p></blockquote><h2 id="mcp-ce-que-vous-exposez-en-branchant-un-serveur" tabindex="-1">MCP : ce que vous exposez en branchant un serveur <a class="header-anchor" href="#mcp-ce-que-vous-exposez-en-branchant-un-serveur" aria-label="Permalink to &quot;MCP : ce que vous exposez en branchant un serveur&quot;">​</a></h2><p><em>Module 4 · slide « MCP : ce que vous exposez en branchant un serveur »</em></p><p>Brancher un serveur, c’est laisser le modèle <strong>décider seul</strong> quelles données partent chez un tiers. Trois questions avant chaque branchement :</p><table tabindex="0"><thead><tr><th>Question</th><th>Ce qu’on vérifie</th></tr></thead><tbody><tr><td><strong>Qui l’exécute ?</strong> Local ou distant</td><td>Le local reste sur la machine. Le distant reçoit ce que le modèle lui envoie.</td></tr><tr><td><strong>Qui l’authentifie ?</strong> Quel jeton, quels droits</td><td>Lecture, écriture, suppression : jamais plus large que la tâche.</td></tr><tr><td><strong>Qui le maintient ?</strong> Officiel ou fork</td><td>Un serveur non maintenu est un risque ouvert.</td></tr></tbody></table><p><strong>Et ce qu’il coûte</strong> : chaque serveur ajoute ses tool definitions à <strong>chaque</strong> appel, avant même le premier message. N’activez que ceux que vous utilisez <strong>vraiment</strong> pour ce projet. Une commande en ligne déjà installée, documentée dans une skill, coûte souvent moins de contexte qu’un serveur MCP complet.</p><h2 id="une-bonne-consigne-devient-une-skill" tabindex="-1">Une bonne consigne devient une skill <a class="header-anchor" href="#une-bonne-consigne-devient-une-skill" aria-label="Permalink to &quot;Une bonne consigne devient une skill&quot;">​</a></h2><p><em>Module 4 · slide « Une bonne consigne devient une skill »</em></p><p>Un <strong>savoir-faire emballé</strong> :</p><ul><li>un <strong>dossier</strong> : un <code>SKILL.md</code>, plus des scripts, références et gabarits ;</li><li>chargée <strong>à la demande</strong>, quand la tâche correspond : la <strong>progressive disclosure</strong> (l’agent ne voit d’abord que le nom et la description) ;</li><li>la <strong>description</strong> dit quoi et quand : c’est elle qui déclenche ;</li><li>testée en <strong>session vierge</strong> : une autre session la suit sans coaching.</li></ul><p>Exemple, la skill « tests-api » :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tests-api/SKILL.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>name: tests-api</span></span>
<span class="line"><span>description: Écrire ou compléter les tests</span></span>
<span class="line"><span>  d&#39;un endpoint. À utiliser dès qu&#39;on</span></span>
<span class="line"><span>  ajoute ou modifie une route.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Un test par cas limite : liste vide,</span></span>
<span class="line"><span>  dernière page, curseur invalide.</span></span>
<span class="line"><span>- Données via tests/factories.</span></span>
<span class="line"><span>- Base de test réelle, pas de mock.</span></span></code></pre></div><ul><li>On n’y met que ce que l’agent <strong>ne peut pas déduire</strong> ; quelques centaines de lignes au plus ; pas de chemins propres à un OS, de versions figées ni d’informations périmées.</li><li>Un <strong>script</strong> embarqué donne le même résultat à chaque fois, là où la même logique en prose est réinterprétée ; et il n’entre pas dans la context window tant que l’agent ne l’ouvre pas.</li><li>Si la skill ne se déclenche pas en session vierge, c’est presque toujours la <strong>description</strong> qu’il faut réécrire.</li></ul><blockquote><p>Une skill ne pèse dans la context window <strong>que quand elle sert</strong>.</p></blockquote><h2 id="ou-ranger-le-contexte-durable" tabindex="-1">Où ranger le contexte durable ? <a class="header-anchor" href="#ou-ranger-le-contexte-durable" aria-label="Permalink to &quot;Où ranger le contexte durable ?&quot;">​</a></h2><p><em>Module 4 · slide « Quiz : où ranger le contexte durable ? »</em></p><p>La règle qui tranche : <strong>à quelle fréquence</strong> le contenu doit-il être chargé ?</p><table tabindex="0"><thead><tr><th>Où</th><th>Chargé</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Instructions projet</strong></td><td>à chaque session</td><td>« Les tests se lancent avec npm test, jamais sur la base de prod » ; « TypeScript strict, handlers dans src/api/handlers »</td></tr><tr><td><strong>Demande initiale</strong></td><td>pour une tâche</td><td>« Pour ce ticket : garder le schéma Page de /rooms »</td></tr><tr><td><strong>Skill</strong></td><td>à la demande, quand la tâche correspond</td><td>« Comment écrire un test d’API selon nos conventions » ; « La procédure de migration de schéma, avec son script »</td></tr><tr><td><strong>Note de reprise</strong></td><td>pour reprendre une session interrompue</td><td>« Étapes 1 à 3 faites, l’étape 4 bloque sur le curseur »</td></tr></tbody></table><ul><li>Piège : « jamais sur la base de prod » pourrait sembler une skill ; elle doit valoir à chaque session, donc instructions projet.</li><li>Tous ces fichiers sont <strong>versionnés et relus comme du code</strong> : ils entrent dans la context window de toute l’équipe.</li></ul><blockquote><p>Plus c’est <strong>chargé souvent</strong>, plus c’est <strong>court</strong> : à chaque session, pour une tâche, à la demande.</p></blockquote><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li>Tools et MCP branchent l’agent sur le SI, mais chaque branchement <strong>expose</strong> quelque chose et <strong>pèse</strong> dans chaque appel.</li><li>Une skill est un savoir-faire <strong>chargé à la demande</strong> ; sa description la déclenche.</li><li>Une consigne que tu répètes <strong>trois fois</strong> mérite une skill, testée en session vierge.</li></ol><p><strong>Mots-clés</strong> : RAG, grounding, tools, MCP, tool definitions, skill, progressive disclosure, instructions projet, demande initiale — voir le glossaire.</p>`,31)])])}const m=n(o,[["render",r]]);export{g as __pageData,m as default};
